import{_ as e,o as r,c as t,a4 as o}from"./chunks/framework.BaMAT_0D.js";const i="/my_note/assets/profiles.BOlHfHDN.png",l="/my_note/assets/shapes.C2iHr1cV.png",h="/my_note/assets/east_compare.ByhANXsp.png",p="/my_note/assets/east_real.B3jkqciY.png",n="/my_note/assets/design.BbuLNlaC.png",s="/my_note/assets/turbulence.VrlUNblE.png",P=JSON.parse('{"title":"托卡马克等离子体物理虚拟仿真实验","description":"","frontmatter":{},"headers":[],"relativePath":"Lab/Physics_Lab/II/Week_5-国家级一流本科课程线上虚拟仿真实验/report.md","filePath":"Lab/Physics_Lab/II/Week_5-国家级一流本科课程线上虚拟仿真实验/report.md","lastUpdated":1793365822000}'),d={name:"Lab/Physics_Lab/II/Week_5-国家级一流本科课程线上虚拟仿真实验/report.md"};function _(c,a,m,b,u,q){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="托卡马克等离子体物理虚拟仿真实验" tabindex="-1">托卡马克等离子体物理虚拟仿真实验 <a class="header-anchor" href="#托卡马克等离子体物理虚拟仿真实验" aria-label="Permalink to &quot;托卡马克等离子体物理虚拟仿真实验&quot;">​</a></h1><p>邓欢桐 3250102223｜肖婷｜2026-10-21</p><h2 id="托卡马克等离子体物理虚拟仿真实验-1" tabindex="-1">托卡马克等离子体物理虚拟仿真实验 <a class="header-anchor" href="#托卡马克等离子体物理虚拟仿真实验-1" aria-label="Permalink to &quot;托卡马克等离子体物理虚拟仿真实验&quot;">​</a></h2><h2 id="_1-实验目的与仪器" tabindex="-1">1 实验目的与仪器 <a class="header-anchor" href="#_1-实验目的与仪器" aria-label="Permalink to &quot;1 实验目的与仪器&quot;">​</a></h2><h3 id="_1-1-实验目的" tabindex="-1">1.1 实验目的 <a class="header-anchor" href="#_1-1-实验目的" aria-label="Permalink to &quot;1.1 实验目的&quot;">​</a></h3><p>本实验以EAST托卡马克为背景，通过装置认识、磁流体力学平衡、EAST磁场中的单粒子轨迹、自行设计平衡剖面以及湍流演示五个模块，学习磁约束等离子体的基本物理过程。重点是把磁面、温度和密度剖面与粒子的回旋、漂移、磁镜反射联系起来，并用控制变量方法比较不同初始条件下的轨道。</p><p>具体目标为：认识真空室、超导线圈及诊断设备的作用；读取不同磁面位形下的平衡分布；整理温度和电子密度的径向取点数据；比较粒子类型、速度大小、方向及入射位置对轨道的影响；区分给定EAST磁场与自行设计磁场；理解湍流和约束性能之间的关系。</p><h3 id="_1-2-仪器、软件与主要参数" tabindex="-1">1.2 仪器、软件与主要参数 <a class="header-anchor" href="#_1-2-仪器、软件与主要参数" aria-label="Permalink to &quot;1.2 仪器、软件与主要参数&quot;">​</a></h3><p>实验使用浙江大学托卡马克等离子体物理虚拟仿真平台。软件提供平衡分布、单粒子运动轨迹、等离子体湍流等模块，以及探针、汤姆逊散射诊断等选项。本次平衡态截图中勾选的诊断方式为探针。快动探针用于局部等离子体参数及涨落测量；磁探针反映局部磁场变化，磁通环测量穿过回路的磁通变化；汤姆逊散射可用于电子温度和密度诊断。</p><p>真空室提供低杂质、低中性气体背景，减少高温等离子体的冷却与污染。冷却系统承担线圈和相关设备的热管理，超导磁体需要低温条件维持工作。纵场线圈建立环向磁场，极向场及等离子体电流共同影响磁面与平衡。截图140的状态栏显示冷却系统打开、真空度10⁻⁵ Pa、环向磁场3.5 T及5.0 K；该低温读数属于装置状态，不能当作等离子体温度。</p><h2 id="_2-实验原理与方法" tabindex="-1">2 实验原理与方法 <a class="header-anchor" href="#_2-实验原理与方法" aria-label="Permalink to &quot;2 实验原理与方法&quot;">​</a></h2><h3 id="_2-1-磁约束与磁流体平衡" tabindex="-1">2.1 磁约束与磁流体平衡 <a class="header-anchor" href="#_2-1-磁约束与磁流体平衡" aria-label="Permalink to &quot;2.1 磁约束与磁流体平衡&quot;">​</a></h3><p>氘氚聚变反应生成氦核和中子，释放约17.6 MeV能量。实验中的D、He及electron用作粒子轨迹研究对象，轨迹演示本身不构成聚变反应发生的证据。高温等离子体无法依靠普通容器壁直接容纳，需利用磁场限制带电粒子的横向运动。</p><p>²H + ³H → ⁴He + n + 17.6 MeV 托卡马克中，环向与极向磁场叠加形成螺旋磁力线。轴对称、静态、各向同性压强近似下，压强梯度与磁力平衡，满足下式。p为等离子体压强，J为电流密度，B为磁感应强度。该关系描述整体平衡，不表示每个粒子都沿同一磁面严格运动。</p><p>∇p = J × B， ∇ × B = μ₀J， ∇ · B = 0</p><h3 id="_2-2-单粒子运动与捕获条件" tabindex="-1">2.2 单粒子运动与捕获条件 <a class="header-anchor" href="#_2-2-单粒子运动与捕获条件" aria-label="Permalink to &quot;2.2 单粒子运动与捕获条件&quot;">​</a></h3><p>带电粒子的运动由洛伦兹力决定。在局部磁场近似均匀、非相对论且电场作用可忽略时，垂直磁场的速度分量引起回旋，平行分量使粒子沿磁力线运动。磁力始终垂直于瞬时速度，因此静磁场本身不做功。</p><p>m dv/dt = q(E + v × B)， rL = m v⊥/(|q|B) m、q分别为粒子质量和电荷，v⊥为垂直磁场的速度。回旋半径公式只适用于局部回旋尺度，不能直接替代复杂托卡马克中导心轨道的宽度。非均匀磁场还使导心发生梯度漂移和曲率漂移；漂移方向与电荷符号有关，粒子运动一般偏离单条磁力线。</p><p>当磁场沿一次回旋的变化很小、磁场变化时间远大于回旋周期时，磁矩μ近似守恒。在静磁场中若总动能也守恒，粒子进入较强磁场区域时垂直动能增加、平行动能减小，平行速度可降至零并反向，形成磁镜反射。</p><p>μ = m v⊥²/(2B) ≈ 常数， v∥² = v² − 2μB/m 若初始磁场为B₀、速度与磁场夹角为α₀，则镜点磁场为Bₘ=B₀/sin²α₀。沿轨道可达的最大磁场足够大时，可能出现反射。捕获粒子在两个反射位置间往返，截面上常形成香蕉形轨道；通行粒子能够环向通行。分类应结合完整运动或平行速度反向证据，单张红色轨迹不能独立证明类别。</p><h3 id="_2-3-实验方法与操作记录范围" tabindex="-1">2.3 实验方法与操作记录范围 <a class="header-anchor" href="#_2-3-实验方法与操作记录范围" aria-label="Permalink to &quot;2.3 实验方法与操作记录范围&quot;">​</a></h3><p>按任务给出的步骤1—4认识和组装装置、启动必要辅助系统；步骤5—8设置最外磁面及剖面参数，观察磁面、磁场、温度和密度分布并取点；步骤9—11选择EAST，比较不同粒子初始条件；步骤12—13选择“平衡态仿真”开展设计磁场轨迹研究；步骤14观察湍流；步骤15要求结束时关闭纵场与极向场线圈电流。现有截图能核实运行中的状态与结果，未将缺少专门记录的组装、测试成绩和关断过程写作已完成事实。</p><p>数据处理时先逐项抄录原表，再计算总速度和便于绘图的标度值，所有原始数值保留。总速度为三个输入分量平方和的平方根，并非独立测量量。由于软件V01、V02、V03沿径向、极向、环向定义，而磁场具有多个分量，不能把V03直接等同于平行磁场速度。</p><h2 id="_3-原始数据与实验现象" tabindex="-1">3 原始数据与实验现象 <a class="header-anchor" href="#_3-原始数据与实验现象" aria-label="Permalink to &quot;3 原始数据与实验现象&quot;">​</a></h2><h3 id="_3-1-平衡态参数与径向取点" tabindex="-1">3.1 平衡态参数与径向取点 <a class="header-anchor" href="#_3-1-平衡态参数与径向取点" aria-label="Permalink to &quot;3.1 平衡态参数与径向取点&quot;">​</a></h3><p>早期平衡态截图137—146中，三种磁面均有实际分布图。截图140及146显示极向场控制量1.2 T·m、a₀=8×10⁶、b₀=10¹⁸、a₁=b₁=0.05；后续193及245显示控制量2 T·m、a₀=10⁶、b₀=10¹⁷、a₁=b₁=0.08。软件虽把该输入框称作“极向场电流”，其说明为μ₀I，故这里保留T·m单位，不误写为安培。两批数据不能当成只改变磁面形状的同一组实验。</p><p>表1分别整理温度和密度各12个测点，来源为截图147—150及152—155。两类测点的R并不相同，表中同一行仅是记录序号，不能据此计算该行的局部压强。裁图未保留磁面标识及Z坐标，因此本表按独立剖面记录处理，不强行归入某一种磁面。</p><p>表1 温度与电子密度径向原始记录 序号 | R_T / m | T 原始值 | R_n / m | nₑ 原始值 1 | 1.50 | 299098.6 | 1.51 | 8.036316E+16 2 | 1.56 | 812538.6 | 1.59 | 2.202451E+17 3 | 1.63 | 2214329 | 1.73 | 6.330626E+17 4 | 1.68 | 3248710 | 1.79 | 8.024129E+17 5 | 1.75 | 5751252 | 1.84 | 9.157880E+17 6 | 1.86 | 7851496 | 1.89 | 9.755398E+17 7 | 1.93 | 7888473 | 1.97 | 9.839521E+17 8 | 2.01 | 6613359 | 2.05 | 8.678351E+17 9 | 2.08 | 4651569 | 2.13 | 6.357734E+17 10 | 2.13 | 2720562 | 2.18 | 4.460939E+17 11 | 2.23 | 579461.5 | 2.24 | 2.502923E+17 12 | 2.30 | 145001.3 | 2.30 | 1.146863E+17 温度图的色标明确标为T(K)，密度图标为nₑ(cm⁻³)，表中数值数量级与早期色标一致。以下按绝对温度K和cm⁻³解释原数值；若正式记录表另有标度表头，应先确认填写值还是单位栏需要修正，不能把百万量级的原数再乘10⁷。原表裁图单位缺失这一限制保留待核实。</p><p>换算示例：T=7 888 473 K对应T/(10⁷ K)=0.7888473；nₑ=9.839521×10¹⁷ cm⁻³对应nₑ/(10¹⁷ cm⁻³)=9.839521。如转为SI密度，1 cm⁻³=10⁶ m⁻³，但不据此断言该教学模型数值等同于EAST实机密度。</p><h3 id="_3-2-剖面与磁面分布观察" tabindex="-1">3.2 剖面与磁面分布观察 <a class="header-anchor" href="#_3-2-剖面与磁面分布观察" aria-label="Permalink to &quot;3.2 剖面与磁面分布观察&quot;">​</a></h3><p><img src="'+i+'" alt="图1 温度和电子密度的12点径向分布；磁面未标定，折线仅连接相邻记录。" loading="lazy"> 已记录温度在R=1.93 m处最大，为7.888473×10⁶ K；密度在R=1.97 m处最大，为9.839521×10¹⁷ cm⁻³。两条剖面均在中部较高、两侧较低。这里的最大只指离散测点中的最大值；温度在1.86 m与1.93 m的读数相近，不足以精确定位连续剖面峰值或磁轴。两种测点位置不同，也不能把0.04 m差异直接解释为物理峰位偏移。</p><p><img src="'+l+'" alt="图2 三角形面、椭圆面和圆形面的真实温度分布视图（140、141、145裁剪）。" loading="lazy"> 三角形面截面具有左右不对称的边界，椭圆面沿Z方向拉长，圆形面则较紧凑。三图都呈现中部温度较高、向边界下降的结构。图像反映了几何形状与温度分布的联系，但缺少各磁面完整取点及统一色标的数值校验，不能进一步给出三种位形的约束优劣排序。</p><p>密度图的色标方向与温度图不同：146、193、245中高密度对应蓝色，不能直接把红色解释为高密度。磁场图显示不同位置的矢量方向随位置变化，体现约束场的空间结构。本次没有仅改变极向场控制量、其余条件完全相同的定量记录，故不拟合电流与轨道宽度关系。</p><h3 id="_3-3-east磁场中的十组粒子轨道记录" tabindex="-1">3.3 EAST磁场中的十组粒子轨道记录 <a class="header-anchor" href="#_3-3-east磁场中的十组粒子轨道记录" aria-label="Permalink to &quot;3.3 EAST磁场中的十组粒子轨道记录&quot;">​</a></h3><p>截图156明确选择EAST，粒子He，初始位置0.25 m，速度分量为(3×10⁶，10⁶，7×10⁵) m/s。该位置是软件给出的相对磁轴的径向位置，不应与平衡剖面中约1.5—2.3 m的大半径R混淆。表2、表3依截图259—261逐行转录；原表中的分类作为填写结果保留，未视为独立验证过的真值。</p><p>表2 EAST粒子初始条件与总速度 组号 | 粒子 | 位置/m | V01/10⁶ | V02/10⁶ | V03/10⁶ | v/10⁶ 1 | He | 0.25 | 3 | 1 | 0.7 | 3.2388 2 | D | 0.25 | 3 | 1 | 0.7 | 3.2388 3 | electron | 0.25 | 3 | 1 | 0.7 | 3.2388 4 | He | 0.25 | 1.5 | 0.5 | 0.35 | 1.6194 5 | He | 0.25 | 6 | 2 | 1.4 | 6.4777 6 | He | 0.25 | 1 | 3 | 0.7 | 3.2388 7 | He | 0.25 | 1 | 0.7 | 3 | 3.2388 8 | He | 0.10 | 3 | 1 | 0.7 | 3.2388 9 | He | 0.15 | 3 | 1 | 0.7 | 3.2388 10 | He | 0.35 | 3 | 1 | 0.7 | 3.2388 表2各速度列单位均为10⁶ m/s，v由输入分量计算。第1组的v为3.2388×10⁶ m/s。第6、7组仅交换V02与V03，速度大小相同，可用于讨论方向的作用。</p><p>表3 EAST轨道参数及原表分类 组号 | ΔR原值 | ΔZ原值 | 原表填写分类 1 | 0.13 | 0.35 | 捕获粒子 2 | 0.13 | 0.35 | 捕获粒子 3 | 0.01 | 0.43 | 捕获粒子 4 | 0.08 | 0.33 | 捕获粒子 5 | 0.10 | 0.20 | 捕获粒子 6 | 0.21 | 0.43 | 捕获粒子 7 | 0.44 | 0.59 | 通行粒子 8 | 0.10 | 0.14 | 通行粒子 9 | 0.13 | 0.20 | 捕获粒子 10 | 0.14 | 0.47 | 捕获粒子 ΔR、ΔZ的精确定义及单位在现有记录表中未标明。报告不把它们自行定义为坐标极值差，也不从截图估计补齐测量值。下文的数值比较均指同一原记录字段的变化，尚不能当作经计量校准的轨道全宽。</p><h3 id="_3-4-east轨道对照与观察" tabindex="-1">3.4 EAST轨道对照与观察 <a class="header-anchor" href="#_3-4-east轨道对照与观察" aria-label="Permalink to &quot;3.4 EAST轨道对照与观察&quot;">​</a></h3><p><img src="'+h+'" alt="图3 EAST原表轨道参数分组对照；纵轴保留原记录值，单位与定义待核实。" loading="lazy"> 粒子类型对照：第1—3组保持位置和速度相同。He与D的ΔR均为0.13，ΔZ均为0.35；电子为0.01、0.43。电子的径向参数较小，但垂直参数并未同步减小，因此不能笼统认为电子所有轨道尺度都最小。相同速度和磁场下，D⁺与He²⁺的质量和电荷都约成两倍，其m/|q|接近，原表相近的记录有物理上的合理性，但不能据此认定两者轨迹在所有条件下完全一致。</p><p>速度大小对照：第4、1、5组三个分量按0.5、1、2倍缩放，总速度分别为1.6194、3.2388、6.4777×10⁶ m/s。ΔR依次0.08、0.13、0.10，ΔZ为0.33、0.35、0.20，未呈单调增加。局部回旋半径随v⊥增加的公式不能直接推出这里两个未定义轨道参数的单调性，还需核对测量定义、轨迹完成状态与取值方法。</p><p>方向对照：第6、7组总速度同为3.2388×10⁶ m/s，但原表分类从捕获改为通行，ΔR从0.21变为0.44，ΔZ从0.43变为0.59。这说明在记录层面，方向变化伴随轨道差异。由于没有平行速度时序数据，报告不据静态图独立确认磁镜反射。</p><p>位置对照：第8、9、1、10组初始位置为0.10、0.15、0.25、0.35 m，ΔZ依次为0.14、0.20、0.35、0.47，ΔR为0.10、0.13、0.13、0.14。原表中0.10 m标为通行，其余为捕获，说明类别不能只由粒子名称或总速度决定。结论限于这组记录，不能推广为某个位置必然通行。</p><p><img src="'+p+'" alt="图4 EAST条件下截面轨迹与三维导心视图（157）；不从图中反算ΔR、ΔZ。" loading="lazy"></p><h3 id="_3-5-自行设计平衡态磁场的轨迹" tabindex="-1">3.5 自行设计平衡态磁场的轨迹 <a class="header-anchor" href="#_3-5-自行设计平衡态磁场的轨迹" aria-label="Permalink to &quot;3.5 自行设计平衡态磁场的轨迹&quot;">​</a></h3><p>与EAST给定磁场不同，探究模块在装置选择中显示“平衡态仿真”，并注明磁面位形。截图263—272为椭圆面，274—283为三角形面，286—295为圆形面，另有297—306补充轨迹。它们证明三类位形均进行了轨迹观察；同一轨道可能有多张截图，故不把截图数量直接写成独立完成次数。</p><p><img src="'+n+'" alt="图5 三种设计磁面下的截面轨迹（263、274、286裁剪）；截图非统一运行终点。" loading="lazy"> 图5中，椭圆面的嵌套磁面沿Z方向拉长，三角形面的边界具有三角度，圆形面的截面接近圆。代表截图的红色轨迹主要位于外侧局部区域，外观与捕获轨道相容，但单帧图像不包含完整往返过程，不能用颜色直接确定分类。其他截图中轨迹覆盖范围不同，反映轨道随初始条件和磁场变化。</p><p>这类比较需要同时控制粒子、初始位置、三个速度分量以及剖面参数。现有三类轨迹图未配套逐行标明全部输入及ΔR、ΔZ的完整测量表，不能把图像差异只归因于磁面形状，也不能把EAST十组表复制成三类磁面的三十组结果。因此保留真实截图开展定性讨论，不制造缺失的定量比较。</p><p>聊天记录307—318保存了三轮逐点读数，其中部分界面与建议磁面顺序不一致。第三轮某磁面读数的Z为0.01 m，密度在R=2.00 m重复且未见2.10 m值，温度和密度也不总按同一比例变化。这些记录已单独转录存档，待核对磁面映射后才能加入严格剖面对照；没有删除异常值或按比例补数。</p><h3 id="_3-6-湍流演示的记录范围" tabindex="-1">3.6 湍流演示的记录范围 <a class="header-anchor" href="#_3-6-湍流演示的记录范围" aria-label="Permalink to &quot;3.6 湍流演示的记录范围&quot;">​</a></h3><p>截图168展示低约束模式下的离子温度梯度模湍流，界面给出的参数包括B=2.1 T、q=1.55、Tₑ≈Tᵢ≈1.2 keV、nₑ=10¹⁹ m⁻³。这是演示模块标注的设置，不能替代平衡态取点读数，也不能与其密度量级混用。</p><h2 id="_4-数据处理与误差分析" tabindex="-1">4 数据处理与误差分析 <a class="header-anchor" href="#_4-数据处理与误差分析" aria-label="Permalink to &quot;4 数据处理与误差分析&quot;">​</a></h2><h3 id="_4-1-湍流的定性解释" tabindex="-1">4.1 湍流的定性解释 <a class="header-anchor" href="#_4-1-湍流的定性解释" aria-label="Permalink to &quot;4.1 湍流的定性解释&quot;">​</a></h3><p><img src="'+s+'" alt="图6 低约束模式下离子温度梯度模湍流演示；颜色表示静电势（168）。" loading="lazy"> 图中沿环向延伸的结构存在红蓝交替，软件说明红色为高静电势、蓝色为低静电势，并介绍长条结构向较短相关长度结构演化及带状流的作用。这些颜色不是温度或密度的直接读数，单帧也不足以测量演化速率。由演示可讨论湍流结构与输运的联系，不能给出不存在的温度、密度演化曲线。</p><p>理论上，微观不稳定性可驱动湍流并增强跨磁面粒子和能量输运，带状流剪切能够调制湍流。L模与H模表示不同约束状态，H模常与边缘输运垒及约束改善有关。本次只有低约束离子温度梯度模的明确截图，不能声称已定量比较L、H模或电子、离子主导的全部演示。</p><h3 id="_4-2-主要不确定性" tabindex="-1">4.2 主要不确定性 <a class="header-anchor" href="#_4-2-主要不确定性" aria-label="Permalink to &quot;4.2 主要不确定性&quot;">​</a></h3><p>第一，鼠标选点与图像刻度限制了空间定位。R的记录通常保留到0.01 m，原始图像还有栅格分辨率，读数末尾的多位小数并不代表同样数量级的绝对精度。峰值定位受相邻测点间隔限制，不能通过插值制造更高空间分辨率。</p><p>第二，温度和密度不是在相同R点读取，Z位置又未在十二点表中保留。把不同行拼成同一点，或把不同批次的数值混在一起，会引入比较偏差。本报告分别绘图，不计算未同点测量的压强、梯度或相关系数。</p><p>第三，实际界面色标与记录表的标度填写存在歧义，极向场输入又是μ₀I而不是I。报告保留原值及标度换算，未把显示精度当成实验不确定度，也未在没有重复测量时杜撰标准差。</p><h3 id="_4-3-轨迹与模型的局限" tabindex="-1">4.3 轨迹与模型的局限 <a class="header-anchor" href="#_4-3-轨迹与模型的局限" aria-label="Permalink to &quot;4.3 轨迹与模型的局限&quot;">​</a></h3><p>ΔR、ΔZ的测量方法未查到明确软件定义，是轨道定量分析的主要限制。坐标最大值减最小值、偏离磁面的距离和轨道半宽并非同一量，现阶段不能互换。原表字段只能按原样比较，其单位和读数是否正确还需软件说明或原始测量记录支持。</p><p>三维轨迹截图的曲线可能尚未覆盖完整周期，截面图也可能叠加多次经过的位置。仅靠闭合外观、红色线条或轨道在某一侧出现，不能充分证明捕获或通行。更可靠的判据是完整时序中平行速度是否在镜点反向，以及粒子能否持续环向通行；本报告未重新运行实验获取该证据。</p><p>虚拟仿真把复杂装置和等离子体作了模型化处理。MHD平衡与单粒子导心轨迹属于不同尺度的描述，后者未必包括碰撞、波粒相互作用或自洽场反馈。因此不能把教学模型曲线直接当成实机放电的定量预测。没有网格、步长及收敛记录时，也无法估算数值积分误差的大小。</p><h2 id="_5-思考题与拓展设计" tabindex="-1">5 思考题与拓展设计 <a class="header-anchor" href="#_5-思考题与拓展设计" aria-label="Permalink to &quot;5 思考题与拓展设计&quot;">​</a></h2><h3 id="_5-1-为什么只有环向磁场还不够" tabindex="-1">5.1 为什么只有环向磁场还不够 <a class="header-anchor" href="#_5-1-为什么只有环向磁场还不够" aria-label="Permalink to &quot;5.1 为什么只有环向磁场还不够&quot;">​</a></h3><p>粒子在局部磁场中回旋，并不意味着其导心永远留在同一磁面。环形几何带来磁场梯度和曲率，离子与电子的漂移方向可不同。极向场与环向场构成螺旋磁力线，使粒子运动在不同位置之间联系起来，是维持整体约束的重要因素。即使存在封闭磁面，轨道宽度、碰撞和湍流仍可造成输运，因此需同时研究平衡、单粒子轨道和湍流。</p><h3 id="_5-2-总速度相同时的轨道差异" tabindex="-1">5.2 总速度相同时的轨道差异 <a class="header-anchor" href="#_5-2-总速度相同时的轨道差异" aria-label="Permalink to &quot;5.2 总速度相同时的轨道差异&quot;">​</a></h3><p>第6、7组总速度相同，而分量方向不同。决定镜反射的是相对于局部磁场的平行与垂直动能分配，并非总速度一个标量。初始位置改变时，局部磁场强度、方向及沿轨道可达的磁场范围也可能改变。原表不同分类提示这些因素需要结合分析，但尚不构成单一阈值判据。</p><h3 id="_5-3-记录方案改进-未实施" tabindex="-1">5.3 记录方案改进（未实施） <a class="header-anchor" href="#_5-3-记录方案改进-未实施" aria-label="Permalink to &quot;5.3 记录方案改进（未实施）&quot;">​</a></h3><p>后续若在课程允许的情况下补充记录，可固定粒子、位置和速度，仅改变一种磁面或一个控制量；每次同时保存输入框、磁面名称、完整运行状态及测量定义。剖面取点固定Z并使用相同R，保留带单位表头。轨迹除截面外还记录平行速度随时间的变化。上述仅为改进建议，未写作已开展的实验。</p><h2 id="_6-实验总结" tabindex="-1">6 实验总结 <a class="header-anchor" href="#_6-实验总结" aria-label="Permalink to &quot;6 实验总结&quot;">​</a></h2><h3 id="_6-1-主要结果" tabindex="-1">6.1 主要结果 <a class="header-anchor" href="#_6-1-主要结果" aria-label="Permalink to &quot;6.1 主要结果&quot;">​</a></h3><p>本次资料包含三种平衡磁面、温度和密度分布、EAST单粒子轨道、自行设计平衡态轨道及低约束湍流演示。十二点温度和密度记录均显示中部较高、边缘较低的径向分布，离散最大值分别位于R=1.93 m和1.97 m。由于两类测点位置不同及磁面未标定，峰位差不能直接解释为不同物理中心。</p><p>EAST十组原记录支持粒子类型、速度大小、方向和位置四类对照。He与D在相同输入下具有相同的原表参数；电子的径向参数较小，垂直参数未同步缩小。固定方向缩放速度时，原表ΔR、ΔZ未随总速度单调增加。保持总速度改变方向，以及保持速度改变初始位置，都伴随轨道参数和原表分类变化。这说明应区分局部回旋规律、复杂导心轨道及记录量的定义。</p><p>自行设计磁场截图区分了椭圆、三角和圆形磁面，反映磁面几何与轨迹空间形态的联系。现有资料不足以给出各位形约束性能排序或定量轨道参数差异。湍流截图的颜色表示静电势，只支持结构层面的定性解释，不能替代温度、密度时间序列。</p><h3 id="_6-2-实验心得" tabindex="-1">6.2 实验心得 <a class="header-anchor" href="#_6-2-实验心得" aria-label="Permalink to &quot;6.2 实验心得&quot;">​</a></h3><p>通过把分布图与轨迹图联系起来，我认识到有磁场与获得良好约束之间还有平衡、轨道宽度及输运等问题。温度和密度剖面反映整体状态，粒子轨迹展示微观运动，湍流则说明即使磁面存在，跨磁面输运仍需考虑，三者应在各自适用条件下理解。</p><p>整理记录也使我注意到，结论不仅取决于曲线是否平滑，还取决于参数、单位、位置和测量定义是否完整。先核对色标、区分批次、保留异常读数，再讨论趋势，比直接套用理想公式更可靠。对尚未核实的轨道参数和分类，保留结论边界也是实验报告的一部分。</p><h3 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h3><p>[1] 浙江大学托卡马克等离子体物理虚拟仿真实验软件：本次保存的平衡态、粒子属性、轨迹及湍流界面截图，2026-10-21。来源编号见表、图注及资料审计。</p><p>[2] 本次原始数据记录截图147—155、259—261，以及聊天记录307—318。聊天读数仅用于审计存档，未作为三磁面定量结论。</p><p>[3] 本课程第5周实验预习报告及本地正式报告模板。预习原文独立标记于报告前部。实验模块和步骤范围依据本次任务提供的实验要求。</p><p>未获得独立官方指导全文，因此不列出未经读取的讲义页码或测量定义。</p>',82)])])}const T=e(d,[["render",_]]);export{P as __pageData,T as default};
